els.clearSearch.addEventListener('click', () => {
  els.search.value = '';
  els.clearSearch.hidden = true;
  state.q = '';
  loadBookmarks();
});

function filterByTag(name) {
  state.tag = name;
  els.activeTag.textContent = name;
  els.activeFilter.hidden = false;
  loadBookmarks();
}

els.clearFilter.addEventListener('click', () => {
  state.tag = '';
  els.activeFilter.hidden = true;
  loadBookmarks();
});

// ---------- Edit ----------

async function openEdit(id) {
  const { status, body } = await api(`/api/bookmarks/${id}`);
  if (status !== 200 || !body) return;
  openEditWith(body);
}

function openEditWith(b, message) {
  editingId = b.id;
  els.editUrl.value = b.url;
  els.editTitle.value = b.title || '';
  els.editDescription.value = b.description || '';
  els.editTags.value = (b.tags || []).join(', ');
  els.editNote.value = b.note || '';
  els.editError.hidden = !message;
  if (message) els.editError.textContent = message;
  loadTagSuggestions();
  els.editDialog.showModal();
}

els.editCancel.addEventListener('click', () => els.editDialog.close());

els.editSave.addEventListener('click', async () => {
  els.editError.hidden = true;
  const payload = {
    url: els.editUrl.value,
    title: els.editTitle.value,
    description: els.editDescription.value,
    note: els.editNote.value,
    tags: parseTags(els.editTags.value),
  };
  const { status, body } = await api(`/api/bookmarks/${editingId}`, {
    method: 'PATCH',
    body: JSON.stringify(payload),
  });
  if (status === 200) {
    els.editDialog.close();
    await loadBookmarks();
    await loadTagSuggestions();
  } else if (status === 409 && body && body.existing) {
    showError(els.editError, 'Another bookmark already uses this address.');
  } else if (body && body.error) {
    showError(els.editError, body.error.message);
  } else {
    showError(els.editError, 'Could not save changes.');
  }
});

els.editRefresh.addEventListener('click', async () => {
  els.editError.hidden = true;
  const { status } = await api(`/api/bookmarks/${editingId}/refresh`, { method: 'POST' });
  if (status === 202) {
    els.editDialog.close();
    await loadBookmarks();
  }
});

// ---------- Delete ----------

function openDelete(id) {
  deletingId = id;
  els.deleteDialog.showModal();
}

els.deleteCancel.addEventListener('click', () => els.deleteDialog.close());

els.deleteConfirm.addEventListener('click', async () => {
  const { status } = await api(`/api/bookmarks/${deletingId}`, { method: 'DELETE' });
  els.deleteDialog.close();
  if (status === 204) {
    await loadBookmarks();
    await loadTagSuggestions();
  }
});

// ---------- Helpers ----------

function showError(el, message) {
  el.textContent = message;
  el.hidden = false;
}

// ---------- Init ----------

(async function init() {
  await loadBookmarks();
  await loadTagSuggestions();
  document.body.setAttribute('data-harness-ready', 'true');
})();
:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --border: #e2e5e9;
  --text: #1c2530;
  --muted: #6b7684;
  --accent: #2f6fed;
  --accent-dark: #1f57c9;
  --danger: #d64545;
  --radius: 10px;
  --shadow: 0 1px 3px rgba(20, 30, 45, 0.08);
}

* { box-sizing: border-box; }

/* Ensure the hidden attribute always wins over class display rules. */
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app-header {
  background: var(--card);
  border-bottom: 1px solid var(--border);
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  position: sticky;
  top: 0;
  z-index: 5;
}

.app-header h1 { font-size: 1.3rem; margin: 0; }

.search-bar {
  display: flex;
  gap: 0.5rem;
  flex: 1;
  min-width: 240px;
}

.search-bar input {
  flex: 1;
}

.container {
  max-width: 900px;
  margin: 0 auto;
  padding: 1.5rem;
}

input, textarea, button {
  font: inherit;
}

input[type="text"], input[type="search"], textarea {
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}

input:focus, textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
  border-color: var(--accent);
}

button {
  cursor: pointer;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  font-weight: 500;
}

button:hover { background: var(--accent-dark); border-color: var(--accent-dark); }

button.ghost {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}
button.ghost:hover { background: #eef0f3; color: var(--text); }

button.danger { background: var(--danger); border-color: var(--danger); }
button.danger:hover { background: #b83636; border-color: #b83636; }

/* Add panel */
.add-panel {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1rem;
  margin-bottom: 1.5rem;
}

.add-row { display: flex; gap: 0.5rem; }
.add-row input { flex: 1; }
.add-row button { white-space: nowrap; }

.add-details { margin-top: 0.75rem; }
.add-details summary { cursor: pointer; color: var(--muted); font-size: 0.9rem; }
.add-details > *:not(summary) { margin-top: 0.5rem; }

.error { color: var(--danger); font-size: 0.9rem; margin: 0.5rem 0 0; }

/* Active filter */
.active-filter {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: var(--muted);
}

/* Bookmark list */
.bookmark-list { display: flex; flex-direction: column; gap: 0.85rem; }

.bookmark {
  display: flex;
  gap: 0.9rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 0.9rem;
}

.bookmark .preview {
  flex: 0 0 120px;
  width: 120px;
  height: 80px;
  border-radius: 8px;
  object-fit: cover;
  background: #eef0f3;
  border: 1px solid var(--border);
}

.bookmark .preview.placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
  font-size: 1.6rem;
}

.bookmark .body { flex: 1; min-width: 0; }

.bookmark .title-row {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.bookmark .favicon { width: 16px; height: 16px; flex: 0 0 16px; border-radius: 3px; }

.bookmark .title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bookmark .title:hover { color: var(--accent); text-decoration: underline; }

.bookmark .url {
  color: var(--muted);
  font-size: 0.82rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark .desc {
  font-size: 0.9rem;
  margin: 0.35rem 0;
