  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bookmark .note {
  font-size: 0.85rem;
  color: var(--muted);
  background: #f7f8fa;
  border-left: 3px solid var(--border);
  padding: 0.3rem 0.5rem;
  border-radius: 4px;
  margin: 0.35rem 0;
  white-space: pre-wrap;
  word-break: break-word;
}

.tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.4rem; }

.tag {
  display: inline-block;
  background: #e8effc;
  color: var(--accent-dark);
  border: none;
  font-size: 0.78rem;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  cursor: pointer;
}
.tag:hover { background: #d5e2fb; }

.bookmark .actions {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 0 0 auto;
}
.bookmark .actions button {
  padding: 0.35rem 0.6rem;
  font-size: 0.82rem;
}

.status-pill {
  font-size: 0.72rem;
  color: var(--muted);
  margin-top: 0.3rem;
}
.status-pill.failed { color: var(--danger); }

/* Empty states */
.empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--muted);
}
.empty-state .empty-title { font-size: 1.15rem; font-weight: 600; color: var(--text); margin-bottom: 0.25rem; }

/* Dialogs */
dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  width: min(480px, 92vw);
  box-shadow: 0 10px 40px rgba(20, 30, 45, 0.25);
}
dialog::backdrop { background: rgba(20, 30, 45, 0.4); }
dialog h2 { margin-top: 0; }
dialog label { display: block; margin-bottom: 0.75rem; font-size: 0.85rem; color: var(--muted); }
dialog label input, dialog label textarea { margin-top: 0.25rem; }

.dialog-actions { display: flex; gap: 0.5rem; align-items: center; margin-top: 0.5rem; }
.dialog-actions .spacer { flex: 1; }

@media (max-width: 560px) {
  .bookmark { flex-direction: column; }
  .bookmark .preview { width: 100%; flex-basis: auto; height: 140px; }
  .bookmark .actions { flex-direction: row; }
}
